insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g5_pe_v1'
from (values
('116.17.b.1.A',3,'In a lead-up game, combining a run with a jump and a throw tests your ability to...','["link locomotor and manipulative skills", "hide", "sit still", "rest"]'::jsonb,0,'Combination skills mix movements.','original'),
('116.17.b.1.A',3,'A hop-step-jump sequence is an example of a...','["cool-down", "locomotor skill combination", "rest period", "quiz"]'::jsonb,1,'Combinations link skills.','original'),
('116.17.b.1.B',4,'A strong long jump begins with a swing of the arms and...','["closing your eyes", "a slow walk", "a powerful push from both legs", "a backward step"]'::jsonb,2,'Arms and legs work together.','original'),
('116.17.b.1.B',4,'A full turn jump can be done in...','["only up", "only forward", "only down", "both directions, left and right"]'::jsonb,3,'Practicing both directions builds skill.','original'),
('116.17.b.1.C',4,'Advanced balancing with equipment could be...','["walking a balance beam while carrying a ball", "resting", "sitting on a mat", "napping"]'::jsonb,0,'Added tasks increase difficulty.','original'),
('116.17.b.1.C',4,'Cross lateralization in complex movement means...','["using one hand only", "coordinating opposite limbs in changing patterns", "standing still", "using no limbs"]'::jsonb,1,'Complexity needs coordination.','original'),
('116.17.b.2.A',3,'Transferring body weight with control during a dynamic activity helps prevent...','["fun", "fitness", "falls and injuries", "speed"]'::jsonb,2,'Control keeps you safe.','original'),
('116.17.b.2.B',3,'Performing a series of pushing and pulling movements, such as a tug-of-war, uses...','["nothing", "only your eyes", "only your legs", "different muscle groups"]'::jsonb,3,'Pushing and pulling use many muscles.','original'),
('116.17.b.3.A',4,'The key elements of manipulative skills include eye on target, follow-through, and...','["body weight transfer", "dropping the ball", "closing your eyes", "sitting"]'::jsonb,0,'Weight transfer adds power and accuracy.','original'),
('116.17.b.3.B',4,'Catching while moving means you...','["close your eyes", "track the object and adjust your steps", "stand still", "turn away"]'::jsonb,1,'Moving catches need tracking.','original'),
('116.17.b.3.C',4,'To shield the ball while dribbling, you keep your body between the ball and the player trying to steal it. That player is called a...','["coach", "referee", "defender", "goalkeeper"]'::jsonb,2,'Shielding keeps the ball safe.','original'),
('116.17.b.3.C',4,'When protecting the ball while dribbling, you should keep the ball on the side...','["toward the defender", "behind your back always", "above your head", "away from the defender"]'::jsonb,3,'Use your off-hand away from pressure.','original'),
('116.17.b.3.D',4,'Combining foot dribbling with a pass in a lead-up game means you...','["move the ball with your feet then pass to a teammate", "only kick hard", "stop", "only run"]'::jsonb,0,'Skills link in games.','original'),
('116.17.b.3.E',4,'Punting a ball requires you to drop the ball and then...','["roll it", "kick it before it hits the ground", "catch it", "hide it"]'::jsonb,1,'Punting kicks a dropped ball.','original'),
('116.17.b.3.E',4,'The proper kicking form includes a follow-through that points...','["backward", "into the sky", "toward your target", "at the ground"]'::jsonb,2,'Follow-through directs the ball.','original'),
('116.17.b.3.F',4,'In volleying, you should get under the ball and use your...','["knees", "elbows", "feet", "fingertips or forearms"]'::jsonb,3,'Contact surfaces control the ball.','original'),
('116.17.b.3.G',4,'When striking with a bat, you should keep your eye on the...','["ball until contact", "floor", "crowd", "sky"]'::jsonb,0,'Eyes on the ball improve contact.','original'),
('116.17.b.3.H',4,'An advanced jump rope routine could include...','["running away", "crossing the rope and double unders", "standing still", "sitting"]'::jsonb,1,'Advanced skills raise difficulty.','original'),
('116.17.b.3.I',4,'Entering a turned long rope with an advanced skill could involve...','["standing still", "holding the rope", "jumping in with a partner or doing a trick", "hiding"]'::jsonb,2,'Advanced entries need timing.','original'),
('116.17.b.4.A',4,'Working in small groups, closing space helps your team...','["spread out", "rest", "stop", "defend and stay connected"]'::jsonb,3,'Closing space shrinks the defender''s gap.','original'),
('116.17.b.4.A',4,'In a small group game, creating open space helps you...','["receive a pass", "hide from the ball", "stop moving", "stand together"]'::jsonb,0,'Open space invites a pass.','original'),
('116.17.b.4.B',4,'Using varied pathways and levels in a group game helps a team...','["stop playing", "confuse defenders", "stay in a line", "rest"]'::jsonb,1,'Variety creates challenge.','original'),
('116.17.b.4.C',4,'Applying speed, direction, and force with a short-handled implement could be...','["sleeping", "walking", "hitting a ball with a paddle at different strengths", "reading a book"]'::jsonb,2,'Control of force matters.','original'),
('116.17.b.6.A',4,'Game skills often follow this order: preparation, movement, force production, and...','["quitting", "hiding", "resting", "follow-through"]'::jsonb,3,'Follow-through completes the skill.','original'),
('116.17.b.6.A',4,'Preparation in a throw means you...','["get set with a balanced stance", "run away", "close your eyes", "sit"]'::jsonb,0,'Preparation sets up the skill.','original'),
('116.17.b.6.B',4,'Working with a partner or group on a skill means you...','["work alone", "share feedback and practice together", "rest", "argue"]'::jsonb,1,'Team practice builds skills.','original'),
('116.17.b.6.C',4,'Game etiquette without a teacher cue means you...','["wait to be told", "argue", "follow rules and show respect on your own", "cheat"]'::jsonb,2,'Self-direction shows maturity.','original'),
('116.17.b.7',4,'A recreational pursuit that requires a map and compass is...','["knitting", "painting", "bowling", "orienteering"]'::jsonb,3,'Orienteering uses navigation skills.','original'),
('116.17.b.7',4,'Which outdoor skill helps you find direction?','["using a compass", "dancing", "baking", "painting"]'::jsonb,0,'Compasses show direction.','original'),
('116.17.b.8.A',3,'Moderate to vigorous activity reduces the risk of...','["laughing", "heart disease", "growing", "learning"]'::jsonb,1,'Activity protects heart health.','original'),
('116.17.b.8.A',3,'Regular activity improves your sleep and your...','["height only", "eye color", "mood and focus", "hair"]'::jsonb,2,'Exercise supports wellbeing.','original'),
('116.17.b.8.B',4,'The FITT principle stands for frequency, intensity, time, and...','["test", "trick", "team", "type"]'::jsonb,3,'FITT includes type of exercise.','original'),
('116.17.b.8.B',4,'In the FITT principle, time means...','["how long each exercise session lasts", "what time of day", "how fast the clock runs", "what time it is in another city"]'::jsonb,0,'Time is the duration.','original'),
('116.17.b.8.C',4,'Which is a skill-related fitness component?','["body composition", "reaction time", "muscular endurance", "flexibility"]'::jsonb,1,'Reaction time is skill-related.','original'),
('116.17.b.9.A',4,'When analyzing a fitness goal, you should ask whether it is...','["ignored", "vague", "specific, measurable, and realistic", "impossible"]'::jsonb,2,'Good goals are SMART.','original'),
('116.17.b.9.B',4,'After tracking your push-up scores, if your numbers are not improving, you could...','["blame the floor", "quit", "hide the scores", "change your training plan"]'::jsonb,3,'Data guides change.','original'),
('116.17.b.10.A',4,'Which food helps your body perform during exercise?','["oatmeal with fruit", "chips", "soda", "candy"]'::jsonb,0,'Whole grains and fruit give lasting energy.','original'),
('116.17.b.10.A',4,'A good pre-game snack is...','["soda", "banana and peanut butter", "cake", "candy"]'::jsonb,1,'Balanced snacks fuel activity.','original'),
('116.17.b.10.B',4,'Dehydration can cause...','["better focus", "extra energy", "tiredness and cramps", "stronger muscles"]'::jsonb,2,'Not enough water harms performance.','original'),
('116.17.b.11.A',4,'Choosing proper equipment means you...','["skip safety items", "share a helmet that doesn''t fit", "use any gear", "select gear that fits the activity and your size"]'::jsonb,3,'Fit and function matter.','original'),
('116.17.b.11.B',4,'Sun safety includes reapplying sunscreen...','["every two hours or after sweating", "once a week", "once a year", "never"]'::jsonb,0,'Sunscreen wears off.','original'),
('116.17.b.11.B',4,'Water safety means swimming...','["in strong currents", "with a buddy and where a lifeguard is present", "in storms", "alone"]'::jsonb,1,'Buddies and lifeguards increase safety.','original'),
('116.17.b.12.A',4,'Accepting responsibility during a game means you...','["quit", "deny it", "own your mistakes and learn from them", "blame the referee"]'::jsonb,2,'Responsibility builds character.','original'),
('116.17.b.12.B',4,'Showing respect for differences includes...','["ignoring", "leaving someone out", "making jokes", "including players of all abilities"]'::jsonb,3,'Inclusion is respect.','original'),
('116.17.b.12.C',4,'Applying self-control after a bad call means you...','["stay calm and keep playing", "walk off", "throw equipment", "yell"]'::jsonb,0,'Self-management helps teams.','original'),
('116.17.b.13.A',4,'Resolving conflict in a socially acceptable way means you...','["fight", "talk it out and find a compromise", "yell", "ignore"]'::jsonb,1,'Compromise solves conflicts.','original'),
('116.17.b.13.A',4,'Responding to winning with dignity means you...','["taunt", "brag", "are humble and respect your opponents", "ignore others"]'::jsonb,2,'Humility is good sportsmanship.','original'),
('116.17.b.13.B',4,'Effective communication during a disagreement includes...','["name calling", "shouting", "interrupting", "active listening"]'::jsonb,3,'Listening reduces conflict.','original'),
('116.17.b.13.C',4,'Empathy is...','["understanding how someone else feels", "ignoring feelings", "being bored", "being angry"]'::jsonb,0,'Empathy is sharing feelings.','original'),
('116.17.b.13.C',4,'Mutual respect means...','["ignoring each other", "treating each other kindly", "only caring about yourself", "making fun of each other"]'::jsonb,1,'Respect goes both ways.','original'),
('116.17.b.14',4,'Perseverance helps an athlete...','["ignore coaching", "blame others", "keep practicing after setbacks", "quit when it gets tough"]'::jsonb,2,'Persistence builds skill.','original'),
('116.17.b.14',4,'Which statement shows perseverance?','["\"I quit.\"", "\"It''s not fair.\"", "\"I''m done.\"", "\"I didn''t get it yet, so I''ll practice more.\""]'::jsonb,3,'"Yet" shows a growth mindset.','original'),
('116.17.b.15',4,'Giving constructive feedback means you...','["offer a helpful suggestion kindly", "laugh", "ignore the person", "criticize harshly"]'::jsonb,0,'Feedback should help.','original'),
('116.17.b.15',4,'When receiving constructive feedback, a good response is to...','["quit", "listen and try the suggestion", "ignore", "argue"]'::jsonb,1,'Openness leads to improvement.','original'),
('116.17.b.16.A',4,'Which activity is moderate in intensity?','["sitting", "sprinting", "brisk walking", "sleeping"]'::jsonb,2,'You can talk but not sing.','original'),
('116.17.b.16.A',4,'Which activity is vigorous in intensity?','["sitting", "slow strolling", "resting", "running laps"]'::jsonb,3,'You can only say a few words.','original'),
('116.17.b.16.B',4,'Analyzing your enjoyment of activities helps you...','["choose activities you will stick with", "pick the least fun", "quit", "avoid exercise"]'::jsonb,0,'Enjoyment keeps you active.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Physical Education' and d.language = 'en'
on conflict (fingerprint) do nothing;
